game.js:
scorp.command({
  name: 'game',
  description: 'Findet ein installiertes Spiel, das zu dir passt, und startet es',
  run(args) {
    const mood = (args || '').trim();
    const moodPart = mood ? `Meine Stimmung oder Wunsch: ${mood}.` : 'Wähle etwas, das gerade zu meiner Stimmung und Uhrzeit passt.';
    scorp.ask(`Skill /game: Suche auf diesem PC nach einem installierten Spiel (Steam-Bibliothek, Startmenü, Epic/GOG, sonst Programme mit Spielnamen) und wähle eines aus, das mir gerade gefallen könnte. ${moodPart} Nenne mir kurz deine Wahl mit einer Begründung und starte das Spiel danach direkt mit launch_app. Falls nichts Passendes installiert ist, sag das ehrlich und schlage ein Browser-Spiel vor.`);
  }
});
